  const dictionaries={'en-US':en,'de-DE':{...en,...de}};
  const read=(key,fallback)=>{try{return localStorage.getItem(key)||fallback;}catch(error){return fallback;}};
  const write=(key,value)=>{try{localStorage.setItem(key,value);}catch(error){}};
  const normalizeLanguage=value=>SUPPORTED_LANGUAGES.includes(value)?value:DEFAULT_LANGUAGE;
  const normalizeCurrency=value=>SUPPORTED_CURRENCIES.includes(value)?value:DEFAULT_CURRENCY;
  let language=normalizeLanguage(read(LANGUAGE_KEY,DEFAULT_LANGUAGE));
