  function formatNumber(value,options={}){return new Intl.NumberFormat(language,options).format(Number(value)||0);}
  function formatDate(value,options={}){const date=value instanceof Date?value:new Date(value);return Number.isNaN(date.getTime())?'':new Intl.DateTimeFormat(language,options).format(date);}
  function rateFor(source,target){if(source===target)return 1;if(typeof rateProvider!=='function')return null;const rate=Number(rateProvider(source,target));return Number.isFinite(rate)&&rate>0?rate:null;}
  function currencyValue(amount,sourceCurrency='EUR',targetCurrency=currency){const source=normalizeCurrency(sourceCurrency),target=normalizeCurrency(targetCurrency),rate=rateFor(source,target);return rate?{amount:Number(amount)*rate,currency:target,converted:source!==target}:{amount:Number(amount),currency:source,converted:false};}
  function formatCurrency(amount,sourceCurrency='EUR',options={}){const {targetCurrency=currency,...formatOptions}=options,value=currencyValue(amount,sourceCurrency,targetCurrency);return new Intl.NumberFormat(language,{style:'currency',currency:value.currency,maximumFractionDigits:0,...formatOptions}).format(value.amount);}
  function setRateProvider(provider){rateProvider=typeof provider==='function'?provider:null;}
  function setPreferences(next={},options={}){const previousLanguage=language,previousCurrency=currency;if(next.language)language=normalizeLanguage(next.language);if(next.currency)currency=normalizeCurrency(next.currency);if(options.persist!==false){write(LANGUAGE_KEY,language);write(CURRENCY_KEY,currency);try{document.cookie='ntc_locale='+encodeURIComponent(language)+'; Path=/; Max-Age=31536000; SameSite=Lax'+(location.protocol==='https:'?'; Secure':'');}catch(error){}}document.documentElement.lang=language;if(options.notify!==false&&(previousLanguage!==language||previousCurrency!==currency))window.dispatchEvent(new CustomEvent('ntc:preferences-changed',{detail:{language,currency}}));return{language,currency};}
  function apply(root=document){document.documentElement.lang=language;root.querySelectorAll('[data-i18n]').forEach(element=>{element.textContent=t(element.dataset.i18n);});for(const [attribute,dataset] of [['placeholder','i18nPlaceholder'],['aria-label','i18nAriaLabel'],['title','i18nTitle'],['alt','i18nAlt']])root.querySelectorAll('[data-'+dataset.replace(/[A-Z]/g,letter=>'-'+letter.toLowerCase())+']').forEach(element=>element.setAttribute(attribute,t(element.dataset[dataset])));const meta=root.querySelector('meta[name="description"]');if(meta)meta.content=t('meta.description');}

  setPreferences({language,currency},{persist:false,notify:false});
  window.NTC_I18N={LANGUAGE_KEY,CURRENCY_KEY,DEFAULT_LANGUAGE,DEFAULT_CURRENCY,SUPPORTED_LANGUAGES,SUPPORTED_CURRENCIES,t,plural,formatNumber,formatDate,formatCurrency,currencyValue,setRateProvider,setPreferences,apply,get language(){return language;},get currency(){return currency;}};
